fn_ap_inbox_delivery_retention.definition:
CREATE OR REPLACE FUNCTION public.fn_ap_inbox_delivery_retention()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  unverified_deadline TIMESTAMPTZ := NEW.received_at + INTERVAL '1 hour';
  failure_deadline TIMESTAMPTZ;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.failed_at IS NOT NULL THEN
      NEW.first_failed_at := NEW.failed_at;
    ELSE
      NEW.first_failed_at := NULL;
    END IF;
  ELSIF OLD.first_failed_at IS NOT NULL THEN
    NEW.first_failed_at := OLD.first_failed_at;
  ELSIF NEW.failed_at IS NOT NULL THEN
    NEW.first_failed_at := NEW.failed_at;
  ELSE
    NEW.first_failed_at := NULL;
  END IF;

  IF NEW.first_failed_at IS NOT NULL THEN
    failure_deadline := NEW.first_failed_at + INTERVAL '7 days';
  END IF;

  IF NEW.verified_at IS NULL THEN
    NEW.retention_expires_at := LEAST(
      COALESCE(NEW.retention_expires_at, unverified_deadline),
      unverified_deadline,
      COALESCE(failure_deadline, unverified_deadline)
    );
  ELSIF NEW.first_failed_at IS NULL THEN
    NEW.retention_expires_at := NULL;
  ELSE
    NEW.retention_expires_at := LEAST(
      COALESCE(OLD.retention_expires_at, NEW.retention_expires_at, failure_deadline),
      COALESCE(NEW.retention_expires_at, failure_deadline),
      failure_deadline
    );
  END IF;

  RETURN NEW;
END;
$function$

fn_ap_inbox_delivery_storage_after_delet.definition:
CREATE OR REPLACE FUNCTION public.fn_ap_inbox_delivery_storage_after_delete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  retained_rows_delta BIGINT;
  retained_bytes_delta BIGINT;
  unverified_rows_delta BIGINT;
  unverified_bytes_delta BIGINT;
BEGIN
  SELECT COUNT(*),
         COALESCE(SUM(OCTET_LENGTH(raw_body)), 0),
         COUNT(*) FILTER (WHERE verified_at IS NULL),
         COALESCE(SUM(OCTET_LENGTH(raw_body)) FILTER (WHERE verified_at IS NULL), 0)
  INTO retained_rows_delta, retained_bytes_delta, unverified_rows_delta, unverified_bytes_delta
  FROM deleted_deliveries;

  UPDATE ap_inbox_delivery_storage_counters
  SET retained_rows = retained_rows - retained_rows_delta,
      retained_raw_body_bytes = retained_raw_body_bytes - retained_bytes_delta,
      unverified_rows = unverified_rows - unverified_rows_delta,
      unverified_raw_body_bytes = unverified_raw_body_bytes - unverified_bytes_delta,
      updated_at = CURRENT_TIMESTAMP
  WHERE singleton;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'ActivityPub inbox storage counter singleton is missing';
  END IF;
  RETURN NULL;
END;
$function$

fn_ap_inbox_delivery_storage_after_inser.definition:
CREATE OR REPLACE FUNCTION public.fn_ap_inbox_delivery_storage_after_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  retained_rows_delta BIGINT;
  retained_bytes_delta BIGINT;
  unverified_rows_delta BIGINT;
  unverified_bytes_delta BIGINT;
  counters ap_inbox_delivery_storage_counters%ROWTYPE;
BEGIN
  SELECT COUNT(*),
         COALESCE(SUM(OCTET_LENGTH(raw_body)), 0),
         COUNT(*) FILTER (WHERE verified_at IS NULL),
         COALESCE(SUM(OCTET_LENGTH(raw_body)) FILTER (WHERE verified_at IS NULL), 0)
  INTO retained_rows_delta, retained_bytes_delta, unverified_rows_delta, unverified_bytes_delta
  FROM inserted_deliveries;

  UPDATE ap_inbox_delivery_storage_counters
  SET retained_rows = retained_rows + retained_rows_delta,
      retained_raw_body_bytes = retained_raw_body_bytes + retained_bytes_delta,
      unverified_rows = unverified_rows + unverified_rows_delta,
      unverified_raw_body_bytes = unverified_raw_body_bytes + unverified_bytes_delta,
      updated_at = CURRENT_TIMESTAMP
  WHERE singleton
    AND (unverified_rows_delta <= 0 OR unverified_rows + unverified_rows_delta <= 10000)
    AND (
      unverified_bytes_delta <= 0
      OR unverified_raw_body_bytes + unverified_bytes_delta <= 268435456
    )
  RETURNING * INTO counters;

  IF FOUND THEN
    RETURN NULL;
  END IF;

  SELECT * INTO counters
  FROM ap_inbox_delivery_storage_counters
  WHERE singleton;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'ActivityPub inbox storage counter singleton is missing';
  END IF;
  RAISE EXCEPTION USING
    ERRCODE = '23514',
    CONSTRAINT = 'ap_inbox_deliveries_unverified_capacity',
    MESSAGE = 'ActivityPub inbox unverified storage capacity exceeded',
    DETAIL = json_build_object(
      'unverifiedRows', counters.unverified_rows,
      'unverifiedRawBodyBytes', counters.unverified_raw_body_bytes,
      'attemptedRows', unverified_rows_delta,
      'attemptedRawBodyBytes', unverified_bytes_delta
    )::TEXT;
END;
$function$

fn_apply_moderation_transparency_daily_r.definition:
CREATE OR REPLACE FUNCTION public.fn_apply_moderation_transparency_daily_rollup(p_occurred_at timestamp with time zone, p_community_id uuid, p_metric text, p_category text, p_delta integer)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE p_day date := (p_occurred_at AT TIME ZONE 'UTC')::date;
BEGIN
  IF p_delta = 0 THEN RETURN; END IF;
  -- Source deletes can hold many FK/cascade row locks. Serialize them against
  -- positive ingestion before either path acquires cohort locks: otherwise two
  -- multi-cohort deletes can interleave their row and advisory lock order.
  IF p_delta < 0 THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('moderation-transparency-rollup-write', 0));
  ELSE
    PERFORM pg_advisory_xact_lock_shared(hashtextextended('moderation-transparency-rollup-write', 0));
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'moderation-transparency-rollup:' || p_day::text || ':'
      || COALESCE(p_community_id::text, 'global') || ':' || p_metric || ':' || p_category,
    0
  ));
  IF EXISTS (
    SELECT 1 FROM moderation_transparency_released_daily_rollups
    WHERE day = p_day AND community_id IS NOT DISTINCT FROM p_community_id
      AND metric = p_metric AND category = p_category
  ) THEN RETURN; END IF;
  IF p_delta < 0 THEN
    PERFORM fn_release_moderation_transparency_daily_rollup(
      p_day, p_community_id, p_metric, p_category,
      date_trunc('day', clock_timestamp() - interval '48 hours') - interval '1 millisecond'
    );
  END IF;
  IF p_delta > 0 THEN
    INSERT INTO moderation_transparency_daily_rollups(day, community_id, metric, category, count, latest_occurred_at)
    VALUES (p_day, p_community_id, p_metric, p_category, p_delta, p_occurred_at)
    ON CONFLICT ON CONSTRAINT moderation_transparency_daily_rollups_key DO UPDATE
      SET count = moderation_transparency_daily_rollups.count + EXCLUDED.count,
          latest_occurred_at = GREATEST(moderation_transparency_daily_rollups.latest_occurred_at, EXCLUDED.latest_occurred_at);
  ELSE
    DELETE FROM moderation_transparency_daily_rollups
      WHERE day = p_day AND community_id IS NOT DISTINCT FROM p_community_id
        AND metric = p_metric AND category = p_category AND count <= -p_delta;
    UPDATE moderation_transparency_daily_rollups
      SET count = count + p_delta
      WHERE day = p_day AND community_id IS NOT DISTINCT FROM p_community_id
        AND metric = p_metric AND category = p_category;
  END IF;
END $function$

fn_create_user_individual_household.definition:
CREATE OR REPLACE FUNCTION public.fn_create_user_individual_household()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  new_individual_id UUID;
  new_household_id UUID;
BEGIN
  -- Create individual
  INSERT INTO individuals DEFAULT VALUES
  RETURNING id INTO new_individual_id;

  -- Link individual to user
  UPDATE users
  SET individual_id = new_individual_id
  WHERE id = NEW.id;

  -- Create household owned by user
  INSERT INTO households (owner_id)
  VALUES (NEW.id)
  RETURNING id INTO new_household_id;

  -- Create membership linking individual to household
  INSERT INTO household_members (household_id, individual_id)
  VALUES (new_household_id, new_individual_id);

  RETURN NEW;
END;
$function$

fn_deduplicate_user_import_topic_recomme.definition:
CREATE OR REPLACE FUNCTION public.fn_deduplicate_user_import_topic_recommendation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.topic_recommendation_post_id IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'user-import-topic-recommendation:' || NEW.user_id::text || ':' || NEW.topic_recommendation_post_id::text,
    0
  ));
  IF EXISTS (
    SELECT 1
    FROM user_import_requests
    WHERE user_id = NEW.user_id
      AND topic_recommendation_post_id = NEW.topic_recommendation_post_id
  ) THEN
    RETURN NULL;
  END IF;

  RETURN NEW;
END $function$

fn_fence_bluesky_follow_receipt_active_u.definition:
CREATE OR REPLACE FUNCTION public.fn_fence_bluesky_follow_receipt_active_users()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.follower_user_id <= NEW.followee_user_id THEN
    PERFORM fn_lock_active_user_for_mutation(NEW.follower_user_id);
    IF NEW.followee_user_id <> NEW.follower_user_id THEN
      PERFORM fn_lock_active_user_for_mutation(NEW.followee_user_id);
    END IF;
  ELSE
    PERFORM fn_lock_active_user_for_mutation(NEW.followee_user_id);
    PERFORM fn_lock_active_user_for_mutation(NEW.follower_user_id);
  END IF;
  RETURN NEW;
END;
$function$

