$function$

fn_guard_copyright_restriction_lifecycle.definition:
CREATE OR REPLACE FUNCTION public.fn_guard_copyright_restriction_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'copyright restrictions are retained legal records' USING ERRCODE = 'check_violation';
  END IF;
  IF ROW(OLD.copyright_notice_target_id, OLD.imposed_at)
    IS DISTINCT FROM ROW(NEW.copyright_notice_target_id, NEW.imposed_at)
    OR (OLD.imposed_by_id IS DISTINCT FROM NEW.imposed_by_id AND NEW.imposed_by_id IS NOT NULL) THEN
    RAISE EXCEPTION 'copyright restriction origin is immutable' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.lifted_at IS NOT NULL
    AND (OLD.lifted_at IS DISTINCT FROM NEW.lifted_at
      OR (OLD.lifted_by_id IS DISTINCT FROM NEW.lifted_by_id AND NEW.lifted_by_id IS NOT NULL)) THEN
    RAISE EXCEPTION 'copyright restriction lift is immutable' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.human_reviewed_at IS NOT NULL
    AND (ROW(OLD.human_reviewed_at, OLD.human_review_action)
      IS DISTINCT FROM ROW(NEW.human_reviewed_at, NEW.human_review_action)
      OR (OLD.human_reviewed_by_id IS DISTINCT FROM NEW.human_reviewed_by_id
        AND NEW.human_reviewed_by_id IS NOT NULL)) THEN
    RAISE EXCEPTION 'copyright restriction human review is immutable' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.human_reviewed_at IS NULL
    AND NEW.human_reviewed_at IS NOT NULL
    AND NEW.human_reviewed_by_id IS NULL THEN
    RAISE EXCEPTION 'copyright restriction human review requires an identified actor' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

fn_guard_membership_grant_activation_per.definition:
CREATE OR REPLACE FUNCTION public.fn_guard_membership_grant_activation_period_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'membership grant activation periods cannot be deleted';
  END IF;

  IF OLD.ended_at IS NULL
    AND NEW.ended_at IS NOT NULL
    AND ROW(
      NEW.id, NEW.membership_grant_id, NEW.user_id, NEW.started_at
    ) IS NOT DISTINCT FROM ROW(
      OLD.id, OLD.membership_grant_id, OLD.user_id, OLD.started_at
    )
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'membership grant activation periods only allow an open-to-ended lifecycle transition';
END $function$

fn_guard_membership_refund_metadata_scan.definition:
CREATE OR REPLACE FUNCTION public.fn_guard_membership_refund_metadata_scan_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE lease_matches BOOLEAN;
BEGIN
  SELECT operation.execution_claim_token = NEW.lease_token INTO lease_matches FROM membership_refund_operation_attempts attempt INNER JOIN membership_operations operation ON operation.id = attempt.membership_operation_id WHERE attempt.id = NEW.membership_refund_operation_attempt_id;
  IF lease_matches IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'membership refund metadata scan lease is stale'; END IF;
  IF TG_OP = 'UPDATE' AND (OLD.completed_at IS NOT NULL OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.membership_refund_operation_attempt_id IS DISTINCT FROM OLD.membership_refund_operation_attempt_id OR (NEW.completed_at IS NOT NULL AND NEW.next_provider_refund_id IS NOT NULL)) THEN RAISE EXCEPTION 'membership refund metadata scan cannot be reopened or rewritten after completion'; END IF;
  RETURN NEW;
END $function$

fn_guard_membership_refund_operation_att.definition:
CREATE OR REPLACE FUNCTION public.fn_guard_membership_refund_operation_attempt_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'membership refund operation attempts cannot be deleted'; END IF;
  IF OLD.provider_refund_id IS NULL AND NEW.provider_refund_id IS NOT NULL AND ROW(NEW.id, NEW.membership_operation_id, NEW.attempt_ordinal, NEW.provider, NEW.environment, NEW.application_id, NEW.provider_idempotency_key, NEW.amount_minor_units, NEW.currency_code, NEW.created_at) IS NOT DISTINCT FROM ROW(OLD.id, OLD.membership_operation_id, OLD.attempt_ordinal, OLD.provider, OLD.environment, OLD.application_id, OLD.provider_idempotency_key, OLD.amount_minor_units, OLD.currency_code, OLD.created_at) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'membership refund operation attempts only allow provider refund ID enrichment';
END $function$

fn_guard_terminal_lifecycle.definition:
CREATE OR REPLACE FUNCTION public.fn_guard_terminal_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  terminal_column TEXT;
  old_row JSONB := to_jsonb(OLD);
  new_row JSONB := to_jsonb(NEW);
  was_terminal BOOLEAN := FALSE;
BEGIN
  FOREACH terminal_column IN ARRAY TG_ARGV LOOP
    IF old_row -> terminal_column <> 'null'::jsonb THEN
      was_terminal := TRUE;
    END IF;
  END LOOP;

  IF was_terminal THEN
    FOREACH terminal_column IN ARRAY TG_ARGV LOOP
      IF old_row -> terminal_column IS DISTINCT FROM new_row -> terminal_column THEN
        RAISE EXCEPTION '% terminal lifecycle cannot transition after completion', TG_TABLE_NAME
          USING ERRCODE = 'check_violation';
      END IF;
    END LOOP;
  END IF;

  RETURN NEW;
END;
