DECLARE v_agent_id uuid;
BEGIN
  SELECT agent_id INTO v_agent_id FROM agent_prompts WHERE id = OLD.id;
  PERFORM fn_lock_moderation_transparency_projection('agent', v_agent_id);
  PERFORM fn_lock_moderation_transparency_projection('prompt', OLD.id);
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

fn_mark_topic_alias_category_mapping_dir.definition:
CREATE OR REPLACE FUNCTION public.fn_mark_topic_alias_category_mapping_dirty()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  dirty_alias_id UUID;
  dirty_alias TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.topic_id IS NULL THEN
      RETURN NEW;
    END IF;
    dirty_alias_id := NEW.id;
    dirty_alias := NEW.alias;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.topic_id IS NOT DISTINCT FROM OLD.topic_id THEN
      RETURN NEW;
    END IF;
    dirty_alias_id := NEW.id;
    dirty_alias := NEW.alias;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.topic_id IS NULL THEN
      RETURN OLD;
    END IF;
    dirty_alias_id := OLD.id;
    dirty_alias := OLD.alias;
  END IF;

  INSERT INTO topic_alias_category_mapping_reconciliations (topic_alias_id, alias)
  VALUES (dirty_alias_id, dirty_alias)
  ON CONFLICT (topic_alias_id) DO UPDATE
  SET alias = EXCLUDED.alias,
      generation = topic_alias_category_mapping_reconciliations.generation + 1,
      updated_at = CURRENT_TIMESTAMP;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

