CREATE OR REPLACE FUNCTION public.fn_sync_ap_post_likes()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_delta INT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_delta := 1;
  ELSIF OLD.deleted_at IS NOT DISTINCT FROM NEW.deleted_at THEN
    RETURN NEW;
  ELSIF OLD.deleted_at IS NULL THEN
    v_delta := -1;
  ELSE
    v_delta := 1;
  END IF;

  INSERT INTO ap_posts (post_id, ap_likes_score, ap_likes_count)
  VALUES (NEW.post_id, GREATEST(v_delta, 0), GREATEST(v_delta, 0))
  ON CONFLICT (post_id) DO UPDATE SET
    ap_likes_score = GREATEST(ap_posts.ap_likes_score + v_delta, 0),
    ap_likes_count = GREATEST(ap_posts.ap_likes_count + v_delta, 0);
  RETURN NEW;
END;
$function$

fn_sync_fediverse_instance_integration_s.definition:
CREATE OR REPLACE FUNCTION public.fn_sync_fediverse_instance_integration_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_status fediverse_integration_statuses;
BEGIN
  -- Serialize concurrent triggers for the same topic: acquire a row-level lock on
  -- topics__fediverse_instances before re-reading the latest change, so whichever
  -- trigger holds the lock last wins and writes the correct (most-recently-committed) value.
  PERFORM topic_id FROM topics__fediverse_instances WHERE topic_id = NEW.topic_id FOR UPDATE;
  SELECT integration_status INTO v_status
  FROM fediverse_instance_integration_changes
  WHERE topic_id = NEW.topic_id
  ORDER BY id DESC LIMIT 1;
  UPDATE topics__fediverse_instances SET integration_status = v_status
  WHERE topic_id = NEW.topic_id AND integration_status IS DISTINCT FROM v_status;
  RETURN NEW;
END;
$function$

