 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_is_discoverable BOOLEAN;
BEGIN
  PERFORM id FROM rss_feeds WHERE id = NEW.rss_feed_id FOR UPDATE;
  SELECT enabled INTO v_is_discoverable
  FROM rss_feed_discoverability_changes
  WHERE rss_feed_id = NEW.rss_feed_id
  ORDER BY id DESC LIMIT 1;
  UPDATE rss_feeds SET is_discoverable = v_is_discoverable
  WHERE id = NEW.rss_feed_id AND is_discoverable IS DISTINCT FROM v_is_discoverable;
  RETURN NEW;
END;
$function$

fn_sync_rss_feed_is_enabled.definition:
CREATE OR REPLACE FUNCTION public.fn_sync_rss_feed_is_enabled()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_enabled BOOLEAN;
BEGIN
  -- Serialize concurrent triggers for the same feed: acquire a row-level lock on
  -- rss_feeds before re-reading the latest change, so whichever trigger holds the
  -- lock last wins and writes the correct (most-recently-committed) value.
  PERFORM id FROM rss_feeds WHERE id = NEW.rss_feed_id FOR UPDATE;
  SELECT enabled INTO v_enabled
  FROM rss_feed_enablement_changes
  WHERE rss_feed_id = NEW.rss_feed_id
  ORDER BY id DESC LIMIT 1;
  UPDATE rss_feeds SET is_enabled = v_enabled
  WHERE id = NEW.rss_feed_id AND is_enabled IS DISTINCT FROM v_enabled;
  RETURN NEW;
END;
$function$

fn_text_to_timestamptz(text_value text).definition:
CREATE OR REPLACE FUNCTION public.fn_text_to_timestamptz(text_value text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  normalized TEXT;
BEGIN
  normalized := TRIM(BOTH E'\t\n\r\f ' FROM text_value);
  IF normalized IS NULL OR normalized = '' OR LOWER(normalized) = 'null' THEN
    RETURN NULL;
  END IF;

  -- Strip a known RFC 822 weekday prefix ("Mon, " … "Sun, ").
  -- Anchored to standard abbreviations; non-standard tokens fall through to the exception handler.
  normalized := regexp_replace(normalized, '^(Mon|Tue|Wed|Thu|Fri|Sat|Sun),\s*', '', 'i');
  -- Collapse a named-zone prefix glued to a numeric offset: "GMT-0700" -> "-0700",
  -- "UTC+05:30" -> "+05:30". PostgreSQL rejects the glued form but accepts the bare offset.
  normalized := regexp_replace(normalized, '(?:GMT|UTC)\s*([+-]\d{1,2}:?\d{2})', '\1', 'i');

  IF normalized ~ '[Zz]$' OR
     normalized ~ '[\+\-]\d{1,2}:?\d{2}$' OR
     normalized ~ ' [A-Z]{3,}$' THEN
    RETURN normalized::timestamptz;
  END IF;
  RETURN timezone('UTC', normalized::timestamp);
EXCEPTION
  -- Best-effort parser over untrusted feed input: any value PostgreSQL still can't parse
  -- degrades to NULL so the generated column falls back to uuid_extract_timestamp(id),
  -- rather than aborting the INSERT and the whole fetchRssFeed job. Three distinct SQLSTATE
  -- codes (22023, 22007, 22009) have already appeared from real feeds; a narrow catch would leak.
  WHEN OTHERS THEN
    RAISE WARNING 'fn_text_to_timestamptz: unparseable date "%" (SQLSTATE: %)', text_value, SQLSTATE;
    RETURN NULL;
END;
$function$

fn_update_updated_at.definition:
CREATE OR REPLACE FUNCTION public.fn_update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$function$

fn_validate_admin_import_row_target.definition:
CREATE OR REPLACE FUNCTION public.fn_validate_admin_import_row_target()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  batch_import_type admin_import_types;
BEGIN
  SELECT import_type
  INTO STRICT batch_import_type
  FROM admin_import_batches
  WHERE id = NEW.batch_id;

  IF NOT (
    (batch_import_type = 'topic' AND NEW.topic_id IS NOT NULL)
    OR (batch_import_type = 'crm_contact' AND NEW.crm_contact_id IS NOT NULL)
    OR (batch_import_type = 'rss_feed' AND NEW.rss_feed_id IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'admin import row target does not match batch import type %', batch_import_type
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

fn_validate_user_landing_page_group_memb.definition:
CREATE OR REPLACE FUNCTION public.fn_validate_user_landing_page_group_member_item_type()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM user_landing_page_items
    WHERE id = NEW.landing_page_item_id
      AND item_type = 'topic_group'
  ) THEN
    RAISE EXCEPTION 'landing_page_item_id must reference a topic_group item';
  END IF;

  RETURN NEW;
END;
$function$
